import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C-si7TFR.js";const p=JSON.parse('{"title":"读写本地环境变量","description":"介绍在工作流中如何设置局部变量，用于临时数据的读写操作。","frontmatter":{"title":"读写本地环境变量","description":"介绍在工作流中如何设置局部变量，用于临时数据的读写操作。","meta":[{"name":"keywords","content":"局部变量,变量读写, 流程变量, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/read_write_local_variable.md","filePath":"zh/read_write_local_variable.md"}'),l={name:"zh/read_write_local_variable.md"};function i(n,a,c,_,d,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h2 id="读写本地环境变量" tabindex="-1">读写本地环境变量 <a class="header-anchor" href="#读写本地环境变量" aria-label="Permalink to &quot;读写本地环境变量&quot;">​</a></h2><p>每个工作流在运行时，都可以维护自己的本地变量(仅作用于当前工作流范围)，用于存储临时的数据。在设计工作流时，在菜单栏上有【本地变量】菜单，点击进去后可以添加该工作流可以读写的本地变量，目前支持字符串和数字两类。</p><p>每个本地变量都有默认值，以及在运行时的值。</p><p><strong>注意：添加本地变量前需要保存工作流先，因为本地变量需要绑定具体的工作流。</strong></p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>在设置了前面的本地变量后，就可以通过【读写本地变量】的应用对变量进行读和写操作。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h2><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><p>支持读和写两种操作。</p><h3 id="key" tabindex="-1">Key <a class="header-anchor" href="#key" aria-label="Permalink to &quot;Key&quot;">​</a></h3><p>读写的变量对象，这里是前面创建的本地环境变量列表。</p><h2 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h2><p>输出具体Key值。</p>',14)])])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
